                                            }`}>
                                                {inv.status}
                                            </span>
                                        </td>
                                    </tr>
                                ))}
                                {myInvoices.length === 0 && (
                                    <tr><td colSpan={4} className="text-center py-8 text-gray-400 italic">No invoices found.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

        </main>
    </div>
  );
};

export default ClientPortal;

