const getLocalCollection = (collection: CollectionName) => {
    const key = `mock_db_${collection}`;
    const stored = localStorage.getItem(key);
    if (stored) return JSON.parse(stored);

    // Initial Seed
    let seed: any[] = [];
    if (collection === 'portfolio') seed = generateMockPortfolio();
    if (collection === 'specials') seed = generateMockSpecials();
    if (collection === 'showroom') seed = generateMockShowroom();
    if (collection === 'bookings') seed = generateMockBookings();
    if (collection === 'expenses') seed = generateMockExpenses();
    if (collection === 'inventory') seed = generateMockInventory();
    if (collection === 'invoices') seed = generateMockInvoices();
    if (collection === 'clients') seed = generateMockClients();

    localStorage.setItem(key, JSON.stringify(seed));
    return seed;
};

const setLocalCollection = (collection: CollectionName, data: any[]) => {
    localStorage.setItem(`mock_db_${collection}`, JSON.stringify(data));
    window.dispatchEvent(new CustomEvent(`db_update_${collection}`));
};

const getLocalDoc = (collection: string, docId: string) => {
    const key = `mock_db_${collection}_${docId}`;
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : null;
};

const setLocalDoc = (collection: string, docId: string, data: any) => {
    localStorage.setItem(`mock_db_${collection}_${docId}`, JSON.stringify(data));
    window.dispatchEvent(new CustomEvent(`db_update_${collection}_${docId}`));
};

// --- AUTH FUNCTIONS ---
export const dbOnAuthStateChange = (callback: (user: any) => void) => {
  if (isSupabaseConfigured && supabase) {
    supabase.auth.getSession().then(({ data: { session } }) => {
      callback(session?.user || null);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      callback(session?.user || null);
    });
    return () => subscription.unsubscribe();
  } else {
    // Mock
    const checkUser = () => {
        const u = localStorage.getItem('mock_user');
        callback(u ? JSON.parse(u) : null);
    };
    checkUser();
    window.addEventListener('storage', checkUser);
    return () => window.removeEventListener('storage', checkUser);
  }
};

export const dbLogin = async (email: string, password?: string) => {
    if (isSupabaseConfigured && supabase) {
        return await supabase.auth.signInWithPassword({ email, password: password || '' });
    } else {
        // Mock Admin Login
        if (email === 'admin@bossalon.com' && password === 'admin') {
            const user = { id: 'mock-admin', email };
            localStorage.setItem('mock_user', JSON.stringify(user));
            window.dispatchEvent(new Event('storage'));
            return { user, error: null };
        }
        return { user: null, error: { message: 'Invalid credentials. Try admin@bossalon.com / admin' } };
    }
};

export const dbLoginWithGoogle = async () => {
    if (isSupabaseConfigured && supabase) {
        const { data, error } = await supabase.auth.signInWithOAuth({
            provider: 'google',
            options: { redirectTo: window.location.origin }
        });
        if (error) throw error;
        return data;
    } else {
        const user = { id: 'mock-google', email: 'mock@gmail.com', user_metadata: { full_name: 'Mock User' } };
        localStorage.setItem('mock_user', JSON.stringify(user));
        window.dispatchEvent(new Event('storage'));
        return { user, session: null }; // Simulate success
    }
};

export const dbLogout = async () => {
    if (isSupabaseConfigured && supabase) {
        await supabase.auth.signOut();
    } else {
        localStorage.removeItem('mock_user');
        window.dispatchEvent(new Event('storage'));
    }
};

// --- DATA FUNCTIONS ---

export const dbSubscribeToCollection = (collection: CollectionName, callback: Listener) => {
    if (isSupabaseConfigured && supabase) {
        // Initial fetch
        supabase.from(collection).select('*').then(({ data, error }) => {
            if (!error && data) callback(data);
        });

        // Realtime subscription
        const channel = supabase.channel(`public:${collection}`)
            .on('postgres_changes', { event: '*', schema: 'public', table: collection }, () => {
                supabase.from(collection).select('*').then(({ data }) => {
                    if (data) callback(data);
                });
            })
            .subscribe();

        return () => { supabase.removeChannel(channel); };
    } else {
        // Mock
        const handler = () => callback(getLocalCollection(collection));
        window.addEventListener(`db_update_${collection}`, handler);
        // Initial call
        callback(getLocalCollection(collection));
        return () => window.removeEventListener(`db_update_${collection}`, handler);
    }
};

export const dbSubscribeToDoc = (collection: string, docId: string, callback: DocListener) => {
    if (isSupabaseConfigured && supabase) {
        supabase.from(collection).select('*').eq('id', docId).single().then(({ data }) => {
            if (data) callback(data);
        });
        // Subscription omitted for simplicity on single docs for now, usually collections are enough
        return () => {}; 
    } else {
        const handler = () => callback(getLocalDoc(collection, docId));
        window.addEventListener(`db_update_${collection}_${docId}`, handler);
        callback(getLocalDoc(collection, docId));
        return () => window.removeEventListener(`db_update_${collection}_${docId}`, handler);
    }
};

export const dbAddItem = async (collection: CollectionName, item: any) => {
    if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from(collection).insert([item]);
        if (error) throw error;
    } else {
        const current = getLocalCollection(collection);
        const newItem = { ...item, id: item.id || crypto.randomUUID(), created_at: new Date().toISOString() };
        setLocalCollection(collection, [...current, newItem]);
    }
};

export const dbUpdateItem = async (collection: CollectionName, item: any) => {
    if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from(collection).update(item).eq('id', item.id);
        if (error) throw error;
    } else {
        const current = getLocalCollection(collection);
        const updated = current.map((i: any) => i.id === item.id ? { ...i, ...item } : i);
        setLocalCollection(collection, updated);
    }
};

export const dbDeleteItem = async (collection: CollectionName, id: string) => {
    if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from(collection).delete().eq('id', id);
        if (error) throw error;
    } else {
        const current = getLocalCollection(collection);
        setLocalCollection(collection, current.filter((i: any) => i.id !== id));
    }
};

export const dbSetDoc = async (collection: string, docId: string, data: any) => {
    if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from(collection).upsert({ id: docId, ...data });
        if (error) throw error;
    } else {
        setLocalDoc(collection, docId, data);
    }
};

export const dbClearCollection = async (collection: CollectionName) => {
    if (isSupabaseConfigured && supabase) {
        // Supabase doesn't have a truncate via client easily without RLS policies allowing delete all
        // We'll delete where id is not null (all)
        const { error } = await supabase.from(collection).delete().neq('id', '00000000-0000-0000-0000-000000000000'); 
        if (error) console.error(error);
    } else {
        setLocalCollection(collection, []);
    }
};

export const dbUploadFile = async (file: File, bucket: string, pathPrefix: string = ''): Promise<string> => {
    if (isSupabaseConfigured && supabase) {
        const fileExt = file.name.split('.').pop();
        const fileName = `${pathPrefix}${Math.random().toString(36).substring(2)}.${fileExt}`;
        const { error } = await supabase.storage.from(bucket).upload(fileName, file);
        if (error) throw error;

        const { data } = supabase.storage.from(bucket).getPublicUrl(fileName);
        return data.publicUrl;
    } else {
        // Mock upload: return local blob URL
        return URL.createObjectURL(file);
    }
};
